examples.setup:
@State private var showsChoices = false
@State private var choices: [String: Bool] = [:]
private let categories = [
    MonarchConsentPreferencesCategory(id: "necessary", label: "Strictly necessary", description: "Sign-in and security.", isRequired: true),
    MonarchConsentPreferencesCategory(id: "analytics", label: "Analytics", description: "How the app is used, inside this app only."),
]

examples.code:
VStack(alignment: .leading) {
    MonarchButton("Privacy choices") { showsChoices = true }
    if ATTrackingManager.trackingAuthorizationStatus != .authorized {
        Text("Cross-app tracking is off; in-app choices still apply.")
            .monarchTextStyle(.caption)
    }
}
.sheet(isPresented: $showsChoices) {
    ScrollView {
        MonarchConsentPreferences(categories: categories, choices: choices) { _, newChoices in
            choices = newChoices
            showsChoices = false
        }
        .padding()
    }
}
